        StorySeries(
            id = "the_rooftop_clock",
            title = "The Rooftop Clock",
            tagline = "A broken rooftop clock helps neighbours rediscover their shared history.",
            parts = listOf(
                StoryPart(1, "Stopped at Noon", listOf("A rooftop clock above the old market stopped at twelve. Residents had grown used to it, but a new student volunteer named Dara wondered why no one repaired it.", "The market manager said the clock had been installed by local craftspeople and had once helped vendors coordinate deliveries.", "Dara asked the history club to investigate before anyone attempted repairs.")),
                StoryPart(2, "The Brass Plate", listOf("A small brass plate named the maker as O. Nwankwo, 1976. The archive listed a clockmaker with that name, but no later records.", "A shop owner remembered that the clockmaker's workshop had closed after a flood. Some tools and notebooks had been donated to the town museum.", "The club arranged to inspect the public records with the curator.")),
                StoryPart(3, "The Notebook", listOf("The notebook contained diagrams and maintenance dates. One page described a replacement part that had never arrived.", "A receipt showed that the part had been ordered from a supplier that later changed its name. The club traced the business through old market directories.", "They discovered that a retired technician still lived nearby.")),
                StoryPart(4, "A Careful Inspection", listOf("The technician agreed to look at the clock with the market manager. He explained that the mechanism needed specialist assessment before anyone touched it.", "He recognised the maker's design and said the clock could likely be restored, but only with appropriate parts and safe access equipment.", "The manager requested a formal assessment and budget.")),
                StoryPart(5, "The Market Map", listOf("While waiting, Dara found an old market map showing the clock as a meeting point. Notes described how vendors used its chime to organise a weekly produce exchange.", "Older residents remembered the exchange, but younger traders had never heard of it.", "The club planned a display explaining how the clock connected the market's past and present.")),
                StoryPart(6, "The Restoration Fund", listOf("The assessment confirmed that restoration was possible. The market committee approved a public fund and published the estimated costs.", "Vendors contributed small amounts, and the local history society offered a grant for preserving the original mechanism.", "Dara recorded every contribution and made sure the committee shared regular updates.")),
                StoryPart(7, "The New Part", listOf("The technician sourced a compatible replacement and completed the specialist work with the authorised maintenance team.", "The clock was tested over several days. Its hands moved steadily, but the chime remained quiet until a final adjustment was approved.", "The club prepared the display and invited former vendors to the reopening.")),
                StoryPart(8, "Stories at the Stall", listOf("At the display, residents shared memories of the produce exchange and the clock's role in busy market mornings.", "Dara recorded the stories with permission and added names only after contributors approved them.", "The committee proposed bringing back a monthly exchange, updated for current traders.")),
                StoryPart(9, "The First Chime", listOf("The clock chimed at noon on reopening day. Vendors paused, visitors applauded, and the technician explained how the original maker's design had been preserved.", "The first produce exchange brought together long-time traders and new small businesses.", "Dara noticed that the clock had become a reason for people to talk across generations.")),
                StoryPart(10, "Time Shared Again", listOf("The market adopted a maintenance schedule and kept the restoration records in the archive.", "The monthly exchange continued, with the clock marking its opening and closing times.", "Dara looked up as the hands moved beyond twelve. The clock had not simply been repaired; it had reminded the market that time was something a community could organise, remember, and share."))
